SCREEN_W = 240
SCREEN_H = 136
TILE = 8

STATE_TITLE    = 0
STATE_GAME     = 1
STATE_GAMEOVER = 2
state = STATE_TITLE

--------------------------------
-- Player
--------------------------------
player = { x=20, y=64, speed=1.2 }

--------------------------------
-- Game State
--------------------------------
room = 1
bullets = {}
enemies = {}

--------------------------------
-- Sprites
--------------------------------
PLAYER_SPR = 256
ENEMY_SPR = { red=261, yellow=262, green=263, blue=264 }
BULLET_SPR = { red=257, yellow=258, green=259, blue=260 }
LAND_TILES = { [0]=true, [2]=true, [3]=true }

--------------------------------
-- TITLE SCREEN
--------------------------------
function draw_title()
 cls(0)
 print("Copyright (C) 2025 Daniel",0,10,12,false,1,true)
 print("Hanrahan Tools and Games",0,20,12,false,1,true)
 print("SPDX-License-Identifier: GPL-3.0-or-later",0,30,12,false,1,true)
 print("A copy of the GNU General Public License is",0,40,12,false,1,true)
 print("included in the file COPYING; if not, see",0,50,12,false,1,true)
 print("<https://www.gnu.org/licenses/>.",0,60,12,false,1,true)
 print("Information just about the stuff in this",0,70,12,false,1,true)
 print("software not covered by the GNU General Public License version 3: This work is",0,80,12,false,1,true)
 print("licensed under Attribution-ShareAlike 4.0 International",0,90,12,false,1,true)
 print("PRESS Z TO START",80,120,12,false,1,true)
end

--------------------------------
-- GAME OVER SCREEN
--------------------------------
function draw_gameover()
 cls(0)
 print("GAME OVER", 90, 50, 12, false, 2, true)
 print("PRESS Z TO RESTART", 60, 80, 12, false, 1, true)
end

--------------------------------
-- Enemy Helper
--------------------------------
function add_enemy(color, tx, ty, speed)
 table.insert(enemies,{
  x = tx*TILE,
  y = ty*TILE,
  init_x = tx*TILE,
  init_y = ty*TILE,
  type = color,
  speed = speed,
  alive = true
 })
end

--------------------------------
-- LOAD RANDOM ROOM
--------------------------------
function load_room()
 enemies = {}
 room = math.random(1,9)

 local slow = 0.3
 local fast = 0.8
 local still = 0

 -- SET PLAYER SPAWN POINT
 if room==1 or room==4 or room==7 then
    player.x = 3*TILE
    player.y = 9*TILE
 elseif room==2 or room==5 or room==8 then
    player.x = 2*TILE
    player.y = 13*TILE
 elseif room==3 or room==6 or room==9 then
    player.x = 2*TILE
    player.y = 13*TILE
 end

 -- ===== ROOMS 1 / 4 / 7 =====
 if room==1 or room==4 or room==7 then
  local sp = (room==4 and slow) or (room==7 and fast) or still
  for x=27,29 do
    for y=3,8 do
      add_enemy("red", x, y, sp)
    end
  end
  for y=9,14 do add_enemy("yellow",27,y,sp) end
  for y=9,14 do add_enemy("green",28,y,sp) end
  for y=9,14 do add_enemy("blue",29,y,sp) end
 end

 -- ===== ROOMS 2 / 5 / 8 =====
 if room==2 or room==5 or room==8 then
  local sp = (room==5 and slow) or (room==8 and fast) or still
  local red={{26,2},{29,3},{28,4},{27,5},{26,6},{29,7},{14,15},{17,14},{16,13},{15,12},{14,11},{17,10}}
  local yellow={{27,2},{26,3},{29,4},{28,5},{27,6},{26,7},{15,15},{14,14},{17,13},{16,12},{15,11},{14,10}}
  local green={{28,2},{27,3},{26,4},{29,5},{28,6},{27,7},{17,13},{16,12},{15,11}}
  local blue={{29,6},{28,7},{29,2},{28,3},{27,4},{26,5},{17,15},{16,14},{15,14},{13,12},{17,11},{16,12}}

  for _,p in ipairs(red) do add_enemy("red",p[1],p[2],sp) end
  for _,p in ipairs(yellow) do add_enemy("yellow",p[1],p[2],sp) end
  for _,p in ipairs(green) do add_enemy("green",p[1],p[2],sp) end
  for _,p in ipairs(blue) do add_enemy("blue",p[1],p[2],sp) end
 end

 -- ===== ROOMS 3 / 6 / 9 =====
 if room==3 or room==6 or room==9 then
  local sp = (room==6 and slow) or (room==9 and fast) or still
  local red={{26,12},{27,13},{28,14},{29,15},{23,6},{24,6},{23,3},{24,3}}
  local yellow={{26,15},{27,14},{28,13},{29,12},{22,4},{23,4},{24,5},{25,5}}
  local green={{27,12},{28,12},{27,15},{28,15},{25,3},{24,4},{23,5},{24,6}}
  local blue={{26,13},{26,14},{29,13},{29,14},{22,3},{23,4},{24,5},{25,6}}

  for _,p in ipairs(red) do add_enemy("red",p[1],p[2],sp) end
  for _,p in ipairs(yellow) do add_enemy("yellow",p[1],p[2],sp) end
  for _,p in ipairs(green) do add_enemy("green",p[1],p[2],sp) end
  for _,p in ipairs(blue) do add_enemy("blue",p[1],p[2],sp) end
 end
end

--------------------------------
-- Fire Bullet
--------------------------------
function fire(color)
 table.insert(bullets,{ x=player.x+8, y=player.y+3, type=color })
end

--------------------------------
-- GAME UPDATE
--------------------------------
function update_game()
 -- MOVE IN ANY DIRECTION
 if btn(0) then player.y = player.y - player.speed end
 if btn(1) then player.y = player.y + player.speed end
 if btn(2) then player.x = player.x - player.speed end
 if btn(3) then player.x = player.x + player.speed end

 -- SHOOTING
 if btnp(4) then fire("green") end
 if btnp(5) then fire("red") end
 if btnp(6) then fire("blue") end
 if btnp(7) then fire("yellow") end

 -- ROOM CHANGE ONLY WHEN CROSSING RIGHT
 if player.x > SCREEN_W then
  player.x = 0
  load_room()
 end

 -- BULLET MOVEMENT
 for i=#bullets,1,-1 do
  bullets[i].x = bullets[i].x + 3
  if bullets[i].x > SCREEN_W then table.remove(bullets,i) end
 end

 -- ENEMY MOVEMENT & RESPAWN
 for _,e in ipairs(enemies) do
  if e.alive then
   e.x = e.x - e.speed
   if e.x + 8 < 0 then
     e.x = e.init_x
     e.y = e.init_y
   end
  end
 end

 -- BULLET VS ENEMY COLLISION (COLOR LOCK)
 for bi=#bullets,1,-1 do
  local b = bullets[bi]
  for _,e in ipairs(enemies) do
   if e.alive and
      b.x<e.x+8 and b.x+8>e.x and
      b.y<e.y+8 and b.y+8>e.y then
    if b.type==e.type then e.alive=false end
    table.remove(bullets,bi)
    break
   end
  end
 end

 -- GAME OVER: LAND TILE OR ENEMY TOUCH
 local tx = math.floor(player.x / TILE)
 local ty = math.floor(player.y / TILE)
 if LAND_TILES[mget(tx, ty)] then
     state = STATE_GAMEOVER
 end
 for _, e in ipairs(enemies) do
    if e.alive and
       player.x < e.x + 8 and player.x + 8 > e.x and
       player.y < e.y + 8 and player.y + 8 > e.y then
        state = STATE_GAMEOVER
    end
 end
end

--------------------------------
-- DRAW GAME
--------------------------------
function draw_game()
 cls(13)
 map((room-1)*30,0,30,17,0,0)
 spr(PLAYER_SPR,player.x,player.y,0,1,false,false,true)
 for _,b in ipairs(bullets) do
   spr(BULLET_SPR[b.type],b.x,b.y,0,1,false,false,true)
 end
 for _,e in ipairs(enemies) do
   if e.alive then
     spr(ENEMY_SPR[e.type],e.x,e.y,0,1,false,false,true)
   end
 end
end

--------------------------------
-- MAIN LOOP
--------------------------------
function TIC()
 if state==STATE_TITLE then
  draw_title()
  if btnp(4) then
   state=STATE_GAME
   load_room()
  end

 elseif state==STATE_GAME then
  update_game()
  draw_game()

 elseif state==STATE_GAMEOVER then
  draw_gameover()
  if btnp(4) then
     bullets = {}
     load_room()
     state = STATE_GAME
  end
 end
end

